package com.clavis.reader;
import android.content.Context;import android.graphics.*;import android.os.*;import android.util.LruCache;import android.view.*;import android.widget.ImageView;import java.lang.ref.WeakReference;import java.util.*;import java.util.concurrent.*;
/** Fetch only visible artwork; share downloads and decoded thumbnails across shelves. */
final class FeedArtwork {
 static final Handler main=new Handler(Looper.getMainLooper());
 static final ExecutorService workers=new ThreadPoolExecutor(6,6,30,TimeUnit.SECONDS,new LinkedBlockingQueue<>());
 static final LruCache<String,Bitmap> memory=new LruCache<String,Bitmap>(8*1024){protected int sizeOf(String key,Bitmap value){return Math.max(1,value.getAllocationByteCount()/1024);}};
 static final Map<String,ArrayList<Request>> flights=new HashMap<>();static final WeakHashMap<View,Scene> scenes=new WeakHashMap<>();static final HashMap<String,Long> failures=new HashMap<>();
 static final class Request {final WeakReference<ImageView> view;final Context context;final String url;final FeedStore.Feed feed;volatile boolean cancelled;boolean started;Request(ImageView v,String u,FeedStore.Feed feed){view=new WeakReference<>(v);context=v.getContext().getApplicationContext();url=u;this.feed=feed;}}
 static final class Scene implements ViewTreeObserver.OnScrollChangedListener,ViewTreeObserver.OnGlobalLayoutListener,View.OnAttachStateChangeListener {
  final WeakReference<View> host;final ArrayList<Request> requests=new ArrayList<>();boolean pending,closed;
  Scene(View view){host=new WeakReference<>(view);view.addOnAttachStateChangeListener(this);view.getViewTreeObserver().addOnScrollChangedListener(this);view.getViewTreeObserver().addOnGlobalLayoutListener(this);}
  public void onScrollChanged(){schedule();}public void onGlobalLayout(){schedule();}public void onViewAttachedToWindow(View v){schedule();}
  public void onViewDetachedFromWindow(View v){closed=true;for(Request r:requests)r.cancelled=true;ViewTreeObserver observer=v.getViewTreeObserver();if(observer.isAlive()){observer.removeOnScrollChangedListener(this);observer.removeOnGlobalLayoutListener(this);}v.removeOnAttachStateChangeListener(this);requests.clear();scenes.remove(v);}
  void schedule(){if(pending||closed)return;pending=true;main.post(()->{pending=false;View root=host.get();if(root==null||closed)return;Rect visible=new Rect();for(Request r:requests){ImageView image=r.view.get();boolean shown=image!=null&&image.isAttachedToWindow()&&image.getGlobalVisibleRect(visible)&&visible.width()>0&&visible.height()>0;r.cancelled=!shown;if(shown){if(!r.started)start(r);}else r.started=false;}});}
 }
 static void bindSource(MainActivity activity,ImageView image,FeedStore.Feed feed){bind(activity,image,"source:"+feed.url,feed);}
 static void bind(MainActivity activity,ImageView image,String url){bind(activity,image,url,null);}
 static void bind(MainActivity activity,ImageView image,String url,FeedStore.Feed feed){if(url==null||url.isEmpty())return;if(url.startsWith("http://"))url="https://"+url.substring(7);Request request=new Request(image,url,feed);image.setTag(request);Bitmap cached=memory.get(url);if(cached!=null){apply(request,cached);return;}Scene scene=scenes.get(activity.mainFrame);if(scene==null){scene=new Scene(activity.mainFrame);scenes.put(activity.mainFrame,scene);}scene.requests.add(request);scene.schedule();}
 static Bitmap decode(Context context,String url)throws Exception{java.io.File file=FeedStore.image(context,url);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),bounds);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>1536)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeFile(file.getAbsolutePath(),options);if(bitmap==null)bitmap=SourceArtwork.ico(file);if(bitmap==null)file.delete();return bitmap;}
 static void apply(Request request,Bitmap bitmap){ImageView image=request.view.get();if(!request.cancelled&&image!=null&&image.getTag()==request){image.setImageTintList(null);image.setImageBitmap(bitmap);}}
 static void start(Request request){request.started=true;Bitmap cached=memory.get(request.url);if(cached!=null){apply(request,cached);return;}Long failed=failures.get(request.url);if(failed!=null&&System.currentTimeMillis()-failed<30000)return;ArrayList<Request> waiting=flights.get(request.url);if(waiting!=null){waiting.add(request);return;}waiting=new ArrayList<>();waiting.add(request);flights.put(request.url,waiting);workers.execute(()->{Bitmap bitmap=null;try{if(!request.cancelled){bitmap=request.feed==null?decode(request.context,request.url):SourceArtwork.load(request.context,request.feed);}}catch(Exception|OutOfMemoryError ignored){}Bitmap result=bitmap;main.post(()->{ArrayList<Request> targets=flights.remove(request.url);if(result!=null){memory.put(request.url,result);failures.remove(request.url);if(targets!=null)for(Request target:targets)apply(target,result);}else if(!request.cancelled){if(failures.size()>256)failures.clear();failures.put(request.url,System.currentTimeMillis());}else if(targets!=null){for(Request target:targets)if(!target.cancelled){target.started=false;start(target);}}});});}
}


